<?php
require __DIR__.'/../api/life/store.php';require __DIR__.'/../api/life/ai.php';require __DIR__.'/../api/life/voice.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$store=new LifeStore($db);$store->initialize('disposable-voice-actions');$ai=new LifeAI($store,['key'=>'test-only','freeOnly'=>true]);$n=0;
function verifyVoice($value){global $n;if(!$value)throw new Exception('Voice action check '.$n.' failed');$n++;}
$r=$ai->mutate($ai->read()['version'],'conversation.new',['title'=>'Voice actions']);$cid=$r['state']['conversations'][0]['id'];$r=$ai->read();$s=$r['state'];$s['conversations'][0]['messages'][]=['role'=>'user','text'=>'My weekend task is Buy groceries','memoryEpoch'=>0];$r=$ai->write($r['version'],$s);
$payload=[];$voice=new LifeVoice($store,$ai,['key'=>'test-only'],function($p)use(&$payload){$payload=$p;return ['name'=>'fake-ephemeral'];});$board=$store->read();$bid=$board['state']['board']['id'];$list=$board['state']['lists'][0]['id'];$session=$voice->start(['version'=>$r['version'],'conversationId'=>$cid,'screen'=>['boardId'=>$bid,'view'=>'board']]);
$instruction=$session['setup']['systemInstruction']['parts'][0]['text'];verifyVoice(str_contains($instruction,'direct access'));verifyVoice(str_contains($instruction,$bid));verifyVoice(str_contains($instruction,$list));verifyVoice(str_contains($instruction,'Buy groceries'));verifyVoice($session['boardVersion']===$board['version']);verifyVoice(count($session['setup']['tools'][0]['functionDeclarations'])===2);
