$result=$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$context['boardVersion'],'text'=>$text,'plan'=>$plan,'requestId'=>'voice-create']);$id=$result['board']['state']['tasks'][0]['id'];verifyVoice($result['planner']['tasks'][0]['id']===$id);verifyVoice($result['board']['state']['tasks'][0]['title']==='Buy groceries');verifyVoice($result['board']['state']['tasks'][0]['listId']===$list);
$again=$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$context['boardVersion'],'text'=>$text,'plan'=>$plan,'requestId'=>'voice-create']);verifyVoice(count($again['board']['state']['tasks'])===1);
$voice->save(['sessionId'=>$session['sessionId'],'turnId'=>'saved-create','user'=>$text,'assistant'=>$result['receipt']['summary'],'commandId'=>$result['receipt']['id']]);
$plan=['authorization'=>'I need you to change that task to Morning groceries','actions'=>[['operation'=>'task.save','arguments'=>json_encode(['id'=>$id,'title'=>'Morning groceries'])]]];$result=$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$store->read()['version'],'text'=>$plan['authorization'],'plan'=>$plan,'requestId'=>'voice-followup']);verifyVoice($result['board']['state']['tasks'][0]['id']===$id);verifyVoice($result['board']['state']['tasks'][0]['title']==='Morning groceries');
$before=$store->read();foreach(['Do not add a task','Maybe add a task','I am thinking about adding a task'] as $text){try{$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$before['version'],'text'=>$text,'plan'=>['authorization'=>'Add a task','actions'=>[['operation'=>'task.save','arguments'=>json_encode(['title'=>'Must not create','listId'=>$list])]]],'requestId'=>'negative-'.md5($text)]);verifyVoice(false);}catch(LifeError $e){verifyVoice($e->status===422);verifyVoice($store->read()===$before);}}
$voice->save(['sessionId'=>$session['sessionId'],'turnId'=>'ask-title','user'=>'Add a task','assistant'=>'What is the task title?']);
$plan=['authorization'=>'Call Cephas','actions'=>[['operation'=>'task.save','arguments'=>json_encode(['title'=>'Call Cephas','listId'=>$list])]]];$result=$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$store->read()['version'],'text'=>'Call Cephas','plan'=>$plan,'requestId'=>'pending-details']);verifyVoice(count($result['board']['state']['tasks'])===2);verifyVoice(empty($result['state']['conversations'][0]['pendingRequest']));
// Raw native speech can never serve as proof that a mutation happened.
$resolved=$voice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'verified-result','text'=>'Change the task','reply'=>'I have moved every task.','commandIds'=>[$result['receipt']['id']]]);verifyVoice($resolved['speakText']);verifyVoice(!str_contains($resolved['reply'],'every task'));verifyVoice(str_contains($resolved['reply'],'Call Cephas'));$repeat=$voice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'verified-result','text'=>'Change the task','reply'=>'I have moved every task.','commandIds'=>[$result['receipt']['id']]]);verifyVoice($repeat['reply']===$resolved['reply']);
$count=count($store->read()['state']['tasks']);$resolved=$voice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'false-claim','text'=>'What would you suggest?','reply'=>'I have moved every task. <ctrl46><ctrl46>']);verifyVoice(str_contains($resolved['reply'],'haven’t changed'));verifyVoice(!str_contains($resolved['reply'],'ctrl46'));verifyVoice(count($store->read()['state']['tasks'])===$count);
$resolved=$voice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'tool-failure','text'=>'Move groceries','reply'=>'Done','toolError'=>'The task name was unclear.']);verifyVoice(str_contains($resolved['reply'],'haven’t changed'));verifyVoice(str_contains($resolved['reply'],'unclear'));
try{$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$store->read()['version'],'text'=>'Add false boy as a task in progress','plan'=>['authorization'=>'Add false boy as a task in progress','actions'=>[['operation'=>'task.move','arguments'=>json_encode(['id'=>$id,'listId'=>$list])]]],'requestId'=>'misheard-add-as-move']);verifyVoice(false);}catch(LifeError $e){verifyVoice($e->status===422);}
// When native voice skips tools, reuse the successful typed-command engine.
$target=array_values(array_filter($store->read()['state']['lists'],fn($l)=>$l['name']==='In Progress'))[0]['id'];$text='Move Morning groceries to In Progress';$agent=new LifeAI($store,['key'=>'test-only','freeOnly'=>true],fn($p)=>['reply'=>'I have done everything','summary'=>'Test','proposals'=>[],'authorization'=>$text,'actions'=>[['operation'=>'task.move','arguments'=>json_encode(['id'=>$id,'listId'=>$target])]]]);$checkedVoice=new LifeVoice($store,$agent,[]);$resolved=$checkedVoice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'fallback-move','text'=>$text,'reply'=>'I moved it']);verifyVoice($resolved['persisted']);verifyVoice($resolved['speakText']);verifyVoice(str_contains($resolved['reply'],'In Progress'));verifyVoice($store->read()['state']['tasks'][0]['listId']===$target);$again=$checkedVoice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'fallback-move','text'=>$text]);verifyVoice($again['reply']===$resolved['reply']);
$agent=new LifeAI($store,['key'=>'test-only','freeOnly'=>true],fn($p)=>['reply'=>'I have moved every task.','summary'=>'Test','proposals'=>[],'actions'=>[]]);$checkedVoice=new LifeVoice($store,$agent,[]);$resolved=$checkedVoice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'fallback-false','text'=>'Move an unknown task to Done','reply'=>'Done']);verifyVoice(str_contains($resolved['reply'],'haven’t changed'));$messages=$resolved['data']['state']['conversations'][0]['messages'];verifyVoice(end($messages)['text']===$resolved['reply']);verifyVoice(!str_contains(end($messages)['text'],'every task'));
// Receipts from another voice session cannot certify this session's claims.
