$before=$store->read();try{$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$before['version'],'text'=>'Move false boy to In Progress','plan'=>['authorization'=>'Move false boy to In Progress','actions'=>[['operation'=>'task.move','arguments'=>json_encode(['id'=>$id,'listId'=>$target])]]],'requestId'=>'wrong-task-name']);verifyVoice(false);}catch(LifeError $e){verifyVoice($e->status===422);verifyVoice($store->read()===$before);}
$resolved=$voice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'native-no-tool','text'=>'Move Morning groceries to Done','reply'=>'I moved it','nativeOnly'=>true]);verifyVoice($resolved['commandId']==='');verifyVoice(str_contains($resolved['reply'],'haven’t changed'));
$resolved=$voice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'native-clarification','text'=>'Move a task to Done','reply'=>'Which task would you like me to move?','nativeOnly'=>true]);verifyVoice(str_contains($resolved['reply'],'Which task'));verifyVoice($resolved['commandId']==='');
verifyVoice(LifeVoice::matchesSpeech('Add a task cold Water the plants to my board','Add a task called Water the plants to my board'));verifyVoice(!LifeVoice::matchesSpeech('Add a task cold Water the plants to my board','Add a task called Wash the car to my board'));$res=$voice->command(['sessionId'=>$session['sessionId'],'boardVersion'=>$store->read()['version'],'text'=>'Add a task cold Water the plants to my board','plan'=>['authorization'=>'Add a task called Water the plants to my board','actions'=>[['operation'=>'task.save','arguments'=>json_encode(['title'=>'Water the plants','listId'=>$list])]]],'requestId'=>'naming-scaffold']);verifyVoice(end($res['board']['state']['tasks'])['title']==='Water the plants');
echo "$n voice action/context checks passed\n";
